(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-638":{scenario:{company:"Ngọc Lâm Civil Works",supervisor:{name:"Đặng Thùy Dung",role:{vi:"Trưởng phòng Hợp đồng & Thanh toán",en:"Head of Contracts & Payments"}},ref_code:"IPC-14",title:{vi:"Đúng điều khoản. Đúng khấu trừ. Đúng giá trị.",en:"Right clause. Right deductions. Right amount."},brief:{vi:"Bạn lập đề nghị thanh toán tạm IPC-14 theo hợp đồng FIDIC Sách Đỏ 1999, giá hợp đồng được chấp nhận 120 000 triệu đồng. Giá trị khối lượng lũy kế đến kỳ này 36 460, lũy kế kỳ trước 28 000 (triệu đồng, chưa gồm thuế GTGT). Giữ lại 10% mỗi kỳ, trần 5% giá hợp đồng; đã giữ 2 800. Tạm ứng còn 8 000 chưa thu hồi. Hãy sửa phân loại hạng mục chống thấm bổ sung và số tiền thanh toán thuần kỳ này, rồi lập báo cáo có căn cứ.",en:"You are preparing interim payment application IPC-14 under a FIDIC 1999 Red Book contract with an accepted contract amount of 120,000 million VND. Cumulative work value is 36,460 now and 28,000 at the previous certificate (million VND, excluding VAT). Retention is 10% per period capped at 5% of the contract amount; 2,800 is already held. An advance of 8,000 remains unrecovered. Correct the class of the extra waterproofing item and the net amount due, then write an evidence-based report."},reference_title:{vi:"Hồ sơ hợp đồng & bảng tính thanh toán đã duyệt",en:"Contract file & approved payment worksheet"},fields:[{id:"ITEM_CLASS",label:{vi:"Phân loại hạng mục chống thấm bổ sung",en:"Class of the extra waterproofing item"},initial:"CLAIM-20.1",expected:"VO-13",choices:["VO-13","CLAIM-20.1","DAYWORK-13.6"],reference:"Chỉ dẫn của Kỹ sư EI-117",ref_value:{vi:"Kỹ sư chỉ dẫn bằng văn bản bổ sung lớp chống thấm thứ hai; hợp đồng có đơn giá công việc tương tự",en:"Engineer's written instruction to add a second waterproofing layer; the contract has rates for similar work"},hint:{vi:"Công việc bổ sung do Kỹ sư chỉ dẫn là thay đổi, định giá theo đơn giá hợp đồng; không phải chờ thủ tục khiếu nại.",en:"Additional work instructed by the Engineer is a variation valued at contract rates; no claim procedure is needed."}},{id:"IPC_NET",label:{vi:"Số tiền thanh toán thuần kỳ này (triệu đồng)",en:"Net amount due this period (million VND)"},initial:"7614",expected:"5499",reference:"Bảng tính đề nghị thanh toán IPC-14",ref_value:{vi:"Lũy kế 36 460; kỳ trước 28 000; giữ lại 10%, trần 5% của 120 000; tạm ứng còn 8 000",en:"Cumulative 36,460; previous 28,000; retention 10%, cap 5% of 120,000; advance outstanding 8,000"},hint:{vi:"Bản nháp đã trừ tiền giữ lại nhưng quên khoản thu hồi tạm ứng của kỳ này.",en:"The draft deducted retention but forgot this period's advance recovery."}}],sop32:{vi:"Giá trị kỳ này = lũy kế hiện tại - lũy kế kỳ trước. Giữ lại 10% giá trị kỳ này nếu tổng giữ lại chưa vượt trần. Thu hồi tạm ứng 25% giá trị kỳ này, không vượt số còn lại. Thanh toán thuần = giá trị kỳ này - giữ lại - thu hồi.",en:"Period value = current cumulative - previous cumulative. Retain 10% of the period value while total retention stays within the cap. Recover the advance at 25% of the period value, not exceeding the balance. Net = period value - retention - recovery."},context:{label:"HỢP ĐỒNG / IPC-14",metrics:[{label:{vi:"Giá hợp đồng được chấp nhận",en:"Accepted contract amount"},value:"120,000 M VND"},{label:{vi:"Tiền giữ lại đến kỳ trước",en:"Retention held to date"},value:"2,800 M VND"},{label:{vi:"Tạm ứng chưa thu hồi",en:"Advance outstanding"},value:"8,000 M VND"}]},crisis:{vi:"Giám đốc dự án nhà thầu: “Thêm 600 m3 đắp nền vào khối lượng kỳ này dù chưa đắp, công nhân cần lương trước Tết. Kỳ sau đắp xong là khớp, Kỹ sư không đo kiểm từng lớp đâu.”",en:"The contractor's project director: “Add 600 m3 of embankment fill to this period even though it is not placed yet; the crew needs wages before Tet. It will match next period and the Engineer never measures every layer.”"},options:{safe:{vi:"Không kê khống khối lượng; báo trưởng phòng hợp đồng, đề xuất phương án hợp lệ như thanh toán vật liệu đã tập kết đủ điều kiện (Điều 14.5) hoặc thỏa thuận hỗ trợ dòng tiền bằng văn bản với chủ đầu tư.",en:"Do not inflate quantities; inform the head of contracts and propose valid options such as payment for eligible materials on site (Sub-Clause 14.5) or a written cash-flow arrangement with the Employer."},shortcut:{vi:"Đưa 600 m3 chưa thi công vào đề nghị thanh toán, kỳ sau điều chỉnh lại.",en:"Include the 600 m3 not yet built in the application and adjust it next period."},wait:{vi:"Nộp đề nghị nháp như cũ và chờ Kỹ sư tự đo kiểm, phát hiện sai sót.",en:"Submit the draft unchanged and wait for the Engineer to measure and find the errors."}},questions:{vi:["Giải thích vì sao hạng mục EI-117 là thay đổi theo Điều 13 và cách bạn tính tiền giữ lại, thu hồi tạm ứng, thanh toán thuần.","Kê khống khối lượng trong đề nghị thanh toán gây hậu quả pháp lý và hợp đồng nào? Có những công cụ hợp lệ nào hỗ trợ dòng tiền?"],en:["Explain why item EI-117 is a Clause 13 variation and how you computed retention, advance recovery and the net amount.","What legal and contractual consequences follow from inflating quantities in a payment application? Which valid tools support cash flow?"]},hints:{vi:["Đọc chỉ dẫn EI-117 và xác định ai khởi xướng thay đổi trước khi chọn điều khoản áp dụng.","Theo SOP mục 3.2, tính giá trị kỳ này trước, rồi lần lượt trừ tiền giữ lại và thu hồi tạm ứng, nhớ kiểm tra trần.","SOP mục 4.2: đề nghị thanh toán chỉ gồm khối lượng thực tế; áp lực kê khống phải báo trưởng phòng hợp đồng."],en:["Read instruction EI-117 and identify who initiated the change before choosing the applicable clause.","Under SOP 3.2, compute the period value first, then deduct retention and advance recovery, checking the cap.","SOP 4.2: an application covers only work actually done; escalate pressure to inflate it to the head of contracts."]}},learning:{summary:{vi:"Kỹ sư hợp đồng và thanh toán xây dựng quản lý vòng đời hợp đồng: rà soát điều kiện hợp đồng, lập và kiểm tra hồ sơ thanh toán, quản lý thay đổi, khiếu nại, bảo lãnh và quyết toán. Ở dự án áp dụng FIDIC, họ bảo đảm mọi thông báo, thời hạn và khoản khấu trừ đúng điều khoản. Nghề đòi hỏi tư duy pháp lý, chính xác số liệu, kỹ năng đàm phán và tính trung thực tuyệt đối.",en:"A construction contracts and payment engineer manages the contract life cycle: reviewing conditions, preparing and checking payment applications, managing variations, claims, guarantees and final accounts. On FIDIC projects they make sure every notice, time limit and deduction follows the clauses. The role needs legal reasoning, numerical accuracy, negotiation skills and absolute honesty."},responsibilities:{vi:["Rà soát điều kiện chung, điều kiện riêng, phụ lục và phân bổ rủi ro của hợp đồng.","Lập, kiểm tra hồ sơ thanh toán tạm, khấu trừ tạm ứng, tiền giữ lại và thuế.","Quản lý thay đổi, định giá công việc bổ sung và theo dõi thời hạn thông báo khiếu nại.","Theo dõi bảo lãnh thực hiện, bảo lãnh tạm ứng, bảo hiểm và gia hạn kịp thời.","Chuẩn bị hồ sơ quyết toán, thanh lý hợp đồng và lưu vết thư từ hợp đồng."],en:["Review general and particular conditions, appendices and the contract's risk allocation.","Prepare and check interim payments, advance recovery, retention and taxes.","Manage variations, value additional work and track claim notice deadlines.","Track performance and advance guarantees and insurances and renew them on time.","Prepare final accounts and contract close-out and keep a trail of contract letters."]},competencies:[{name:{vi:"Hiểu điều kiện hợp đồng FIDIC",en:"FIDIC conditions"},desc:{vi:"Nắm điều khoản thanh toán, thay đổi, khiếu nại, thời hạn và giải quyết tranh chấp.",en:"Master the payment, variation, claim, time limit and dispute clauses."}},{name:{vi:"Tính toán thanh toán",en:"Payment calculation"},desc:{vi:"Tính chính xác giá trị kỳ, tiền giữ lại, thu hồi tạm ứng, điều chỉnh giá và thuế.",en:"Compute period value, retention, advance recovery, price adjustment and tax accurately."}},{name:{vi:"Quản lý thay đổi & khiếu nại",en:"Variations & claims"},desc:{vi:"Phân biệt thay đổi, khiếu nại, công nhật; lập hồ sơ đủ căn cứ, đúng hạn.",en:"Distinguish variations, claims and daywork; prepare well-evidenced, timely submissions."}},{name:{vi:"Đàm phán & thư tín hợp đồng",en:"Negotiation & correspondence"},desc:{vi:"Viết thư hợp đồng rõ ràng, lập luận chặt chẽ, giữ quan hệ hợp tác.",en:"Write clear, well-argued contract letters while keeping relationships cooperative."}},{name:{vi:"Liêm chính",en:"Integrity"},desc:{vi:"Không kê khống, không che giấu rủi ro hợp đồng với bất kỳ bên nào.",en:"Never inflate claims or hide contractual risk from any party."}}],knowledge:{vi:["Điều kiện hợp đồng FIDIC Sách Đỏ 1999 và 2017 cho công trình do chủ đầu tư thiết kế.","FIDIC 1999: Điều 13 (thay đổi), Điều 14 (giá hợp đồng và thanh toán), Điều 20 (khiếu nại, tranh chấp).","Nghị định 37/2015/NĐ-CP về hợp đồng xây dựng, sửa đổi bởi Nghị định 50/2021/NĐ-CP.","Bộ luật Dân sự 2015 về hợp đồng và Luật Thương mại 2005 về phạt vi phạm, bồi thường thiệt hại.","Quy định hiện hành về thuế giá trị gia tăng và hóa đơn điện tử trong thanh toán xây dựng."],en:["FIDIC 1999 and 2017 Red Book conditions for works designed by the Employer.","FIDIC 1999: Clause 13 (variations), Clause 14 (contract price and payment), Clause 20 (claims and disputes).","Decree 37/2015/ND-CP on construction contracts, amended by Decree 50/2021/ND-CP.","Civil Code 2015 on contracts and Commercial Law 2005 on penalties and damages.","Current rules on value added tax and e-invoices in construction payments."]},tools:["Phần mềm quản lý hợp đồng và thanh toán","Microsoft Excel","Hệ thống quản lý thư từ dự án","Phần mềm dự toán xây dựng","Sổ theo dõi bảo lãnh và thời hạn"],kpis:{vi:["Tỷ lệ đề nghị thanh toán được Kỹ sư xác nhận không phải điều chỉnh.","Số thông báo khiếu nại bị quá hạn (mục tiêu bằng 0).","Thời gian trung bình từ khi nộp đề nghị đến khi nhận tiền.","Số bảo lãnh hết hạn mà chưa được gia hạn (mục tiêu bằng 0)."],en:["Share of payment applications certified without adjustment.","Claim notices issued late (target zero).","Average time from application to receipt of payment.","Guarantees expired without renewal (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra sổ thời hạn: thông báo khiếu nại, bảo lãnh, bảo hiểm sắp đến hạn.",en:"Check the deadline log: claim notices, guarantees and insurances falling due."},{time:"09:30",vi:"Đối chiếu biên bản nghiệm thu khối lượng với bảng giá để lập đề nghị thanh toán.",en:"Match measurement records with the bill of quantities to build the application."},{time:"11:00",vi:"Định giá hạng mục thay đổi theo đơn giá hợp đồng, chuẩn bị hồ sơ trình Kỹ sư.",en:"Value variation items at contract rates and prepare the submission to the Engineer."},{time:"14:00",vi:"Họp với Kỹ sư làm rõ các khoản khấu trừ và khối lượng còn tranh chấp.",en:"Meet the Engineer to clarify deductions and disputed quantities."},{time:"16:30",vi:"Soạn thư hợp đồng, cập nhật nhật ký thay đổi và lưu hồ sơ.",en:"Draft contract letters, update the variation log and file the records."}],mistakes:{vi:["Quên thu hồi tạm ứng hoặc tính tiền giữ lại vượt trần quy định trong hợp đồng.","Xử lý công việc do Kỹ sư chỉ dẫn như khiếu nại, làm chậm định giá và thanh toán.","Gửi thông báo khiếu nại quá thời hạn 28 ngày, có thể mất quyền đòi gia hạn và chi phí."],en:["Forgetting advance recovery or retaining beyond the contractual cap.","Treating Engineer-instructed work as a claim, delaying valuation and payment.","Giving claim notice after the 28-day limit, which can forfeit time and cost entitlement."]},career:[{vi:"Kỹ sư khối lượng, thanh toán",en:"Quantity and payment engineer"},{vi:"Kỹ sư hợp đồng",en:"Contracts engineer"},{vi:"Trưởng phòng hợp đồng",en:"Contracts manager"},{vi:"Giám đốc thương mại dự án",en:"Commercial director"}],glossary:[{term:"IPC",vi:"Chứng chỉ thanh toán tạm do Kỹ sư phát hành, xác nhận số tiền chủ đầu tư phải trả mỗi kỳ.",en:"Interim payment certificate issued by the Engineer stating the amount the Employer must pay each period."},{term:"Retention money",vi:"Tiền giữ lại mỗi kỳ để bảo đảm nghĩa vụ của nhà thầu, hoàn trả theo các mốc hợp đồng.",en:"Money withheld each period to secure the contractor's obligations, released at contract milestones."},{term:"Variation",vi:"Thay đổi công việc do Kỹ sư chỉ dẫn hoặc chấp thuận theo Điều 13.",en:"Change to the Works instructed or approved by the Engineer under Clause 13."},{term:"Advance payment",vi:"Khoản tạm ứng ban đầu cho nhà thầu, thu hồi dần qua các kỳ thanh toán.",en:"Initial advance to the contractor, recovered progressively through payment certificates."},{term:"Time bar",vi:"Cơ chế làm mất quyền khiếu nại nếu không thông báo trong thời hạn quy định.",en:"Mechanism that removes the right to claim if notice is not given within the stated period."}],quiz:[{q:{vi:"Giá trị kỳ này 4 000 triệu đồng, giữ lại 10%, thu hồi tạm ứng 25%. Số tiền thanh toán thuần là bao nhiêu?",en:"The period value is 4,000 million VND, retention 10% and advance recovery 25%. What is the net amount?"},options:{vi:["3 600 triệu","3 000 triệu","2 600 triệu","2 400 triệu"],en:["3,600 million","3,000 million","2,600 million","2,400 million"]},answer:2,explain:{vi:"4 000 - 400 - 1 000 = 2 600 triệu đồng.",en:"4,000 - 400 - 1,000 = 2,600 million VND."}},{q:{vi:"Theo FIDIC Sách Đỏ 1999, nhà thầu phải gửi thông báo khiếu nại trong bao lâu kể từ khi biết sự kiện?",en:"Under the FIDIC 1999 Red Book, within how long must the contractor give notice of a claim after becoming aware of the event?"},options:{vi:["14 ngày","56 ngày","90 ngày","28 ngày"],en:["14 days","56 days","90 days","28 days"]},answer:3,explain:{vi:"Điều 20.1 yêu cầu thông báo trong 28 ngày; quá hạn có thể mất quyền gia hạn thời gian và thanh toán bổ sung.",en:"Sub-Clause 20.1 requires notice within 28 days; late notice can forfeit extension of time and additional payment."}},{q:{vi:"Giám đốc dự án yêu cầu đưa khối lượng chưa thi công vào đề nghị thanh toán. Bạn làm gì?",en:"The project director asks you to include unbuilt quantities in the payment application. What do you do?"},options:{vi:["Từ chối, báo trưởng phòng và đề xuất cơ chế hợp lệ như thanh toán vật liệu đã tập kết","Đưa vào rồi kỳ sau trừ lại","Đưa vào một nửa khối lượng","Gửi luôn để Kỹ sư tự quyết định"],en:["Refuse, inform the head of contracts and propose valid tools such as payment for materials on site","Include it and deduct next period","Include half of it","Submit and let the Engineer decide"]},answer:0,explain:{vi:"Kê khống là gian lận thanh toán; hợp đồng có công cụ hợp lệ để hỗ trợ dòng tiền khi đủ điều kiện.",en:"Inflating quantities is payment fraud; the contract offers valid tools to support cash flow when conditions are met."}},{q:{vi:"Kỹ sư chỉ dẫn bằng văn bản làm thêm một hạng mục. Theo FIDIC, đây là gì?",en:"The Engineer instructs additional work in writing. Under FIDIC, what is this?"},options:{vi:["Khiếu nại theo Điều 20","Thay đổi theo Điều 13","Sự kiện bất khả kháng","Sai sót của nhà thầu"],en:["A Clause 20 claim","A Clause 13 variation","A force majeure event","A contractor defect"]},answer:1,explain:{vi:"Chỉ dẫn thay đổi của Kỹ sư là thay đổi theo Điều 13, được định giá và đưa vào chứng chỉ thanh toán.",en:"An Engineer's change instruction is a Clause 13 variation, valued and included in payment certificates."}}],tools_en:["Contract and payment management software","Microsoft Excel","Project correspondence management system","Construction cost estimating software","Guarantee and deadline tracking register"]}}})})(window.KKR);
